try:
    print('>>> f = delattr')
    print('>>> x = (1, 2)')
    print('>>> y = bytearray()')
    print('>>> f(x, y)')
    f = delattr
    x = (1, 2)
    y = bytearray()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
